using Microsoft.Playwright;
using Xunit;

namespace BARANG.Backoffice.E2ETests;

public sealed class PurchaseOrdersE2ETests : IAsyncLifetime
{
    private IPlaywright playwright = null!; private IBrowser browser = null!; private IBrowserContext context = null!; private IPage page = null!;
    private readonly string baseUrl = Environment.GetEnvironmentVariable("BARANG_E2E_BASE_URL") ?? "http://localhost:5100";
    public async ValueTask InitializeAsync(){playwright=await Playwright.CreateAsync();browser=await playwright.Chromium.LaunchAsync(new(){Headless=true,ExecutablePath=Environment.GetEnvironmentVariable("BARANG_E2E_BROWSER_PATH")??@"C:\Program Files\Google\Chrome\Application\chrome.exe"});context=await browser.NewContextAsync(new(){Locale="en-US",ViewportSize=new(){Width=1440,Height=1000}});page=await context.NewPageAsync();await page.GotoAsync(baseUrl+"/login",new(){WaitUntil=WaitUntilState.NetworkIdle});await page.Locator("#username").FillAsync(Environment.GetEnvironmentVariable("BARANG_E2E_USERNAME")??"admin");await page.Locator("#password").FillAsync(Environment.GetEnvironmentVariable("BARANG_E2E_PASSWORD")??"BarangDev@2026");await page.Locator("button[type=submit]").ClickAsync();await page.WaitForLoadStateAsync(LoadState.NetworkIdle);if(new Uri(page.Url).AbsolutePath=="/company"){await page.Locator(".company-list form:has(input[name=companyId][value='42f0e459-6095-45bb-aa13-f38126d91d9c']) button[type=submit]").ClickAsync();await page.WaitForURLAsync(url=>new Uri(url).AbsolutePath!="/company");}}
    [Fact]
    public async Task Purchase_order_grid_and_real_multiline_draft_work(){await page.GotoAsync(baseUrl+"/culture?culture=en&returnUrl=%2Fworkspace%2Finventory",new(){WaitUntil=WaitUntilState.NetworkIdle});await page.GotoAsync(baseUrl+"/workspace/inventory?section=orders",new(){WaitUntil=WaitUntilState.NetworkIdle});var grid=page.Locator("[data-purchase-order-grid]");await Assertions.Expect(grid).ToBeVisibleAsync();await Assertions.Expect(grid.Locator(".crud-search input")).ToHaveCountAsync(1);await Assertions.Expect(grid.Locator(".crud-toolbar button")).ToHaveCountAsync(1);await Assertions.Expect(grid).Not.ToContainTextAsync("Refresh");await grid.GetByRole(AriaRole.Button,new(){Name="Add purchase order",Exact=true}).ClickAsync();var dialog=page.GetByRole(AriaRole.Dialog,new(){Name="Add purchase order"});await Choose(dialog.Locator("input[name=supplier]"),"SUP-DEV-002");await Choose(dialog.Locator("input[name=warehouse]"),"EW0_1788283843295");await Choose(dialog.Locator("input[name=product]"),"PRD-DEV-001");await Choose(dialog.Locator("input[name=sku]"),"SKU-DEV-001");await dialog.Locator("input[type=number]").First.FillAsync("2");await dialog.GetByRole(AriaRole.Button,new(){Name="Add line",Exact=true}).ClickAsync();await Assertions.Expect(dialog.Locator("tbody tr")).ToHaveCountAsync(1);await Choose(dialog.Locator("input[name=product]"),"PRD-DEV-002");await Choose(dialog.Locator("input[name=sku]"),"SKU-DEV-002");await dialog.Locator("input[type=number]").First.FillAsync("3");await dialog.GetByRole(AriaRole.Button,new(){Name="Add line",Exact=true}).ClickAsync();await Assertions.Expect(dialog.Locator("tbody tr")).ToHaveCountAsync(2);await dialog.GetByRole(AriaRole.Button,new(){Name="Save draft",Exact=true}).ClickAsync();await Assertions.Expect(dialog).ToBeVisibleAsync();await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("Purchase order saved.");dialog=page.GetByRole(AriaRole.Dialog);await dialog.GetByRole(AriaRole.Button,new(){Name="Cancel",Exact=true}).ClickAsync();await Assertions.Expect(grid).ToContainTextAsync("PO-");var row=grid.Locator("tbody tr").Last;await Assertions.Expect(row.GetByRole(AriaRole.Button,new(){Name="View",Exact=true})).ToBeVisibleAsync();await Assertions.Expect(row.GetByRole(AriaRole.Button,new(){Name="Edit",Exact=true})).ToBeVisibleAsync();await Assertions.Expect(row.GetByRole(AriaRole.Button,new(){Name="Submit",Exact=true})).ToBeVisibleAsync();await Assertions.Expect(row.GetByRole(AriaRole.Button,new(){Name="Delete",Exact=true})).ToBeVisibleAsync();var view=row.GetByRole(AriaRole.Button,new(){Name="View",Exact=true});await view.FocusAsync();await view.PressAsync("Enter");await Assertions.Expect(page.GetByRole(AriaRole.Dialog,new(){Name="View purchase order"})).ToBeVisibleAsync();}
    [Fact]
    public async Task Purchase_order_sourcing_error_is_top_level_and_preserves_form_state(){await page.GotoAsync(baseUrl+"/culture?culture=en&returnUrl=%2Fworkspace%2Finventory",new(){WaitUntil=WaitUntilState.NetworkIdle});await page.GotoAsync(baseUrl+"/workspace/inventory?section=orders",new(){WaitUntil=WaitUntilState.NetworkIdle});var grid=page.Locator("[data-purchase-order-grid]");await grid.GetByRole(AriaRole.Button,new(){Name="Add purchase order",Exact=true}).ClickAsync();var dialog=page.GetByRole(AriaRole.Dialog);await Choose(dialog.Locator("input[name=supplier]"),"I14S1788268154");await Choose(dialog.Locator("input[name=warehouse]"),"EW0_1788283843295");await Choose(dialog.Locator("input[name=product]"),"PRD-DEV-001");await Choose(dialog.Locator("input[name=sku]"),"SKU-DEV-001");await dialog.Locator("input[type=number]").First.FillAsync("1");await dialog.GetByRole(AriaRole.Button,new(){Name="Add line",Exact=true}).ClickAsync();await dialog.GetByRole(AriaRole.Button,new(){Name="Save draft",Exact=true}).ClickAsync();var alert=dialog.GetByRole(AriaRole.Alert);await Assertions.Expect(alert).ToContainTextAsync("No valid supplier sourcing relation exists");await Assertions.Expect(dialog.Locator("input[name=supplier]")).ToHaveValueAsync("Phase14 Supplier - I14S1788268154");await Assertions.Expect(dialog.Locator("tbody tr")).ToHaveCountAsync(1);await Choose(dialog.Locator("input[name=supplier]"),"SUP-DEV-001");await dialog.GetByRole(AriaRole.Button,new(){Name="Save draft",Exact=true}).ClickAsync();await Assertions.Expect(dialog.GetByRole(AriaRole.Alert)).ToHaveCountAsync(0);await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("Purchase order saved.");}
    [Fact]
    public async Task Purchase_order_uses_the_canonical_jalali_date_control_in_persian(){await page.GotoAsync(baseUrl+"/culture?culture=fa&returnUrl=%2Fworkspace%2Finventory",new(){WaitUntil=WaitUntilState.NetworkIdle});await page.GotoAsync(baseUrl+"/workspace/inventory?section=orders",new(){WaitUntil=WaitUntilState.NetworkIdle});var grid=page.Locator("[data-purchase-order-grid]");await Assertions.Expect(grid).ToBeVisibleAsync();await grid.GetByRole(AriaRole.Button,new(){Name="افزودن سفارش خرید",Exact=true}).ClickAsync();var dialog=page.GetByRole(AriaRole.Dialog);await Assertions.Expect(dialog.Locator(".locale-date-input")).ToHaveCountAsync(2);await Assertions.Expect(dialog.Locator(".locale-date-input").First).ToHaveAttributeAsync("data-calendar-culture","fa");await Assertions.Expect(dialog.Locator("input[type=date]")).ToHaveCountAsync(0);var expected=dialog.Locator("input[name=expected-date]");await Assertions.Expect(expected).ToBeVisibleAsync();await expected.FillAsync("1405/01/15");await Assertions.Expect(expected).Not.ToHaveValueAsync("");await Choose(dialog.Locator("input[name=supplier]"),"SUP-DEV-002");await Choose(dialog.Locator("input[name=warehouse]"),"EW0_1788283843295");await Choose(dialog.Locator("input[name=product]"),"PRD-DEV-001");await Choose(dialog.Locator("input[name=sku]"),"SKU-DEV-001");await dialog.Locator("input[type=number]").First.FillAsync("1");await dialog.GetByRole(AriaRole.Button,new(){Name="افزودن ردیف",Exact=true}).ClickAsync();await dialog.GetByRole(AriaRole.Button,new(){Name="ذخیره پیش‌نویس",Exact=true}).ClickAsync();await Assertions.Expect(dialog).ToBeVisibleAsync();await Assertions.Expect(page.GetByRole(AriaRole.Status)).ToContainTextAsync("سفارش خرید ذخیره شد.");dialog=page.GetByRole(AriaRole.Dialog);await dialog.GetByRole(AriaRole.Button,new(){Name="انصراف",Exact=true}).ClickAsync();await Assertions.Expect(grid.Locator("tbody tr").Last).ToBeVisibleAsync();await Assertions.Expect(grid.Locator("tbody tr").First).ToContainTextAsync("1405/01/15");}
    private async Task Choose(ILocator input,string search){await input.FillAsync(search);var options=input.Locator("xpath=.. ").Locator("[role=option]");await Assertions.Expect(options).ToHaveCountAsync(1);await options.First.ClickAsync();await Assertions.Expect(input).Not.ToHaveValueAsync("");}
    public async ValueTask DisposeAsync(){await context.DisposeAsync();await browser.DisposeAsync();playwright.Dispose();}
}

